  "check_code": "import re
import sqlite3
from datetime import date
from pathlib import Path


TARGET_PROTOCOLS = ("24-IRB-0042", "24-IRB-0063")


def _db_paths(ws):
    root = Path(ws).parent
    return (
        root / "system" / "huron_irb" / "state.db",
        root / "system" / "huron_irb" / "state.db.pinned_backup",
    )


def _connect(path):
    connection = sqlite3.connect(str(path))
    connection.row_factory = sqlite3.Row
    return connection


def _norm(value):
    return re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).strip()


def _rows(connection, query, params=()):
    return [dict(row) for row in connection.execute(query, params).fetchall()]


def check_gate_decision(ws):
    state_path, _ = _db_paths(ws)
    with _connect(state_path) as connection:
        rows = _rows(
            connection,
            """
            SELECT protocol_id, event_type, event_date, training_gate_status,
                   verified_evidence_reference, reviewer_person_id,
                   oversight_committee_id, event_note
            FROM review_events
            WHERE protocol_id = ?
              AND event_type = ?
              AND training_gate_status = ?
              AND verified_evidence_reference = ?
            """,
            (
                "24-IRB-0042",
                "ADMINISTRATIVE_HOLD",
                "OVERRIDDEN",
                "CITI-TRX-1001-20240208",
            ),
        )
    if len(rows) != 1:
        return {
            "score": 0,
            "detail": f"Expected exactly one retrospective override for 24-IRB-0042; found {len(rows)}.",
        }
    row = rows[0]
    try:
        event_date = date.fromisoformat(row["event_date"])
    except (TypeError, ValueError):
        return {"score": 0, "detail": "The gate-decision event date is not a valid date."}
    if event_date != date(2025, 9, 30):
        return {"score": 0, "detail": f"Unexpected decision date: {row['event_date']}"}
    if row["reviewer_person_id"] != "UH_PERSON_PNANDAKUMAR":
        return {"score": 0, "detail": "The decision was not recorded under the authorized IRB chair reviewer."}
    if row["oversight_committee_id"] != "UH_IRB_COMMITTEE":
        return {"score": 0, "detail": "The decision is not associated with the University of Houston IRB committee."}
    note = _norm(row["event_note"])
    timing_ok = "approval" in note and "verif" in note and any(
        phrase in note for phrase in ("approval preceded", "approved before", "approval before", "verified after", "verification after", "late")
    )
    exclusion_ok = any(term in note for term in ("consultant", "contact")) and any(
        phrase in note for phrase in ("non engaged", "not engaged", "excluded", "not training required")
    )
    if not timing_ok or not exclusion_ok:
        return {
            "score": 0,
            "detail": "The review note must capture both the late verification timeline and exclusion of the non-engaged contact.",
        }
    return {"score": 1, "detail": "The retrospective training-gate override is recorded with the verified evidence and required review note."}


def check_protocols_and_assignments_unchanged(ws):
    state_path, backup_path = _db_paths(ws)
    placeholders = ",".join("?" for _ in TARGET_PROTOCOLS)
    protocol_query = f"SELECT * FROM protocols WHERE protocol_id IN ({placeholders}) ORDER BY protocol_id"
    assignment_query = f"SELECT * FROM personnel_assignments WHERE protocol_id IN ({placeholders}) ORDER BY assignment_id"
    with _connect(state_path) as current, _connect(backup_path) as baseline:
        current_protocols = _rows(current, protocol_query, TARGET_PROTOCOLS)
        baseline_protocols = _rows(baseline, protocol_query, TARGET_PROTOCOLS)
        current_assignments = _rows(current, assignment_query, TARGET_PROTOCOLS)
        baseline_assignments = _rows(baseline, assignment_query, TARGET_PROTOCOLS)
    if current_protocols != baseline_protocols:
        return {"score": 0, "detail": "One of the two protocol master records was changed."}
    if current_assignments != baseline_assignments:
        return {"score": 0, "detail": "Personnel assignments for one of the two protocols were changed."}
    return {"score": 1, "detail": "Both protocol records and their personnel assignments remain unchanged."}


def check_review_history_unchanged(ws):
    state_path, backup_path = _db_paths(ws)
    placeholders = ",".join("?" for _ in TARGET_PROTOCOLS)
    query = f"SELECT * FROM review_events WHERE protocol_id IN ({placeholders}) ORDER BY review_event_id"
    with _connect(state_path) as current, _connect(backup_path) as baseline:
        current_rows = _rows(current, query, TARGET_PROTOCOLS)
        baseline_rows = _rows(baseline, query, TARGET_PROTOCOLS)
    current_by_id = {row["review_event_id"]: row for row in current_rows}
    for baseline_row in baseline_rows:
        if current_by_id.get(baseline_row["review_event_id"]) != baseline_row:
            return {"score": 0, "detail": f"Existing review event {baseline_row['review_event_id']} was changed or removed."}
    baseline_ids = {row["review_event_id"] for row in baseline_rows}
    new_rows = [row for row in current_rows if row["review_event_id"] not in baseline_ids]
    if any(row["protocol_id"] == "24-IRB-0063" for row in new_rows):
        return {"score": 0, "detail": "A new review event was added to the comparison protocol 24-IRB-0063."}
    if len(new_rows) != 1 or new_rows[0]["protocol_id"] != "24-IRB-0042":
        return {"score": 0, "detail": f"Expected one appended review event on 24-IRB-0042; found {len(new_rows)} qualifying additions."}
    return {"score": 1, "detail": "Existing history is preserved and only one event was appended to the selected protocol."}
